import React from 'react';

interface ScarewareMobileHeaderProps {
  currentPhase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme' | 'escape';
  onAdvancePhase: (phase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme' | 'escape') => void;
}

const phaseNames: Record<string, string> = {
  norton: 'Norton',
  microsoft: 'Microsoft',
  google: 'Google',
  malwarebytes: 'Malwarebytes',
  generic: 'Legal Threats',
  advanced: 'Tech Support',
  extreme: 'Ransomware',
  escape: 'Escape Guide',
};

const ScarewareMobileHeader: React.FC<ScarewareMobileHeaderProps> = ({ currentPhase, onAdvancePhase }) => {
  return (
    <header
      style={{
        position: 'sticky',
        top: 0,
        left: 0,
        right: 0,
        zIndex: 10001,
        background: '#222',
        color: '#fff',
        padding: '0.75rem 1rem',
        borderBottom: '2px solid #007bff',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        fontSize: '1.1rem',
        fontWeight: 600,
        boxShadow: '0 2px 8px rgba(0,0,0,0.12)'
      }}
    >
      <span>{phaseNames[currentPhase] || 'Scareware'}</span>
      {/* Add navigation or actions as needed */}
    </header>
  );
};

export default ScarewareMobileHeader;
